ZO_CreateStringId("LAW_MENU_DESCRIPTION", "An all-in-one werewolf quality-of-life addon")
ZO_CreateStringId("LAW_CONFIRM_POUNCE", "Confirm <<1>>")
ZO_CreateStringId("LAW_CONFIRM_POUNCE_TOOLTIP", "While enabled, <<1>> only fires when the button has been held for a moment; this avoids accidental leaps in situations where you do not want to move (such as Bahsei)\n\nThis does not block its melee morph <<2>>")
ZO_CreateStringId("LAW_CONFIRM_ULTIMATE", "Confirm <<1>>")
ZO_CreateStringId("LAW_CONFIRM_ULTIMATE_TOOLTIP", "While enabled and in werewolf form, <<1>> only fires when the button has been held for a moment; this avoids accidentally turning back into your humanoid disguise \n\nThis does not block its morph <<2>>")
ZO_CreateStringId("LAW_CONFIRM_TIMEOUT", "Confirmation Hold Time (ms)")
ZO_CreateStringId("LAW_CONFIRM_TIMEOUT_TOOLTIP", "How long you have to hold the button to confirm the ability you want to use")
ZO_CreateStringId("LAW_POUNCE_INDICATOR", "Confirmation Animation")
ZO_CreateStringId("LAW_POUNCE_INDICATOR_TOOLTIP", "Shows an animation while confirming, so you can tell how far along you are")
ZO_CreateStringId("LAW_ROAR_PANEL", "Show <<1>> Buff Tracker")
ZO_CreateStringId("LAW_ROAR_PANEL_TOOLTIP", "Shows a timer panel tracking the <<1>> and <<2>> buffs on you")
ZO_CreateStringId("LAW_ROAR_PANEL_TOOLTIP_GAMEPAD", "Shows a timer panel tracking the <<1>> and <<2>> buffs on you\n\nOn console, type |ccc922f/awroar|r and move the panel with the right stick, then type it again to lock it")
ZO_CreateStringId("LAW_PROWL_PANEL", "Show <<1>> Status Tracker")
ZO_CreateStringId("LAW_PROWL_PANEL_TOOLTIP", "Shows a timer panel tracking your <<1>> status")
ZO_CreateStringId("LAW_PROWL_PANEL_TOOLTIP_GAMEPAD", "Shows a timer panel tracking your <<1>> status\n\nOn console, type |ccc922f/awprowl|r and move the panel with the right stick, then type it again to lock it")
ZO_CreateStringId("LAW_CLAW_FURY_RANGE", "Show <<1>> Range")
ZO_CreateStringId("LAW_CLAW_FURY_RANGE_TOOLTIP", "Shows the ability's range while <<1>> is up")
ZO_CreateStringId("LAW_TIMEOUT", "<<1>> Idle Threshold (ms)")
ZO_CreateStringId("LAW_TIMEOUT_TOOLTIP", "When this slider is above 0, the addon blocks <<1>> in combat\n\n<<1>> only comes back in combat once you have spent this long without dealing direct damage")
ZO_CreateStringId("LAW_FEEDING_PRIORITY", "Prioritize <<1>>")
ZO_CreateStringId("LAW_FEEDING_PRIORITY_TOOLTIP", "While enabled, the addon raises <<1>>'s synergy priority to the highest")
ZO_CreateStringId("LAW_PANEL_MOVE_MSG", "LAW: Panel move %s")
